def priority(item: float, bins: np.ndarray) -> np.ndarray:
    feasible = bins >= item
    if np.any(feasible):
        remaining = bins - item
        avg_remaining = np.mean(remaining[feasible])
        scores = -np.abs(remaining - avg_remaining)
        return np.where(feasible, scores, -np.inf)
    else:
        return np.full_like(bins, -np.inf)
